/* Shared display helpers for force projections and moments. */
const Engineering=(()=>{
 const axes=['x','y','z'],round=n=>Math.abs(n)<.0000005?'0':Number(n.toFixed(4)).toString(),num=n=>n<-.0000005?mo('−')+'<mn>'+round(-n)+'</mn>':'<mn>'+round(n)+'</mn>',text=s=>'<mtext>'+M.esc(s)+'</mtext>',tuple=v=>'('+v.map(round).join(', ')+')';
 const vec=(v,unit='')=>v.map((n,i)=>(i?mo('+'):'')+mo('(')+num(n)+mo(')')+mi(['i','j','k'][i])).join('')+text(unit?' '+unit:'');
 const fields=(id,title,unit,values)=>`<fieldset><legend>${title} · ${unit}</legend><div class="coordinate-row">${axes.map((axis,i)=>`<label>${axis}<input id="${id}${i}" type="number" step="any" min="-10000" max="10000" value="${values[i]}"></label>`).join('')}</div></fieldset>`;
 function read(ids){const groups=ids.map(id=>axes.map((_,i)=>$(id+i).value));if(groups.flat().some(v=>v.trim()===''||!Number.isFinite(Number(v))||Math.abs(Number(v))>10000))throw Error('Enter every component as a finite number between −10,000 and 10,000.');return groups.map(group=>group.map(Number));}
 function sync(id,values){values.forEach((value,i)=>$(id+i).value=value);}
 function row(index,title,context,formula,explanation){return `<div class="step" data-equation="${context}"><div class="step-title"><span>${String(index).padStart(2,'0')}</span>${title}</div><div class="math">${formula}</div><p>${explanation}</p></div>`;}
 function symbols(items,formulas,cards){Object.assign(Learning.symbols,items);Learning.formulas={...Learning.formulas,...formulas};Learning.cards.push(...cards);renderReference();}
 function diagram(id,view,items,angles=[],unitOverride,measurement){
  const pair={xy:[0,1],xz:[0,2],yz:[1,2]}[view],project=p=>pair?[p[pair[0]],p[pair[1]]]:[.866*(p[0]-p[1]),p[2]-.5*(p[0]+p[1])],fitExtent=Math.max(1,...items.flatMap(item=>[...item.start,...item.end].map(Math.abs)))*1.15;
  const units=unitOverride||(id==='projectionDiagram'?'N':id==='examCalculationDiagram'&&items.some(item=>item.label==='A')?'N':'m'),roadmap=id.startsWith('roadmapDiagram'),points=[project([0,0,0]),...items.flatMap(item=>[project(item.start),project(item.end)]),...(measurement?['start','end'].map(endpoint=>project(items[measurement.index][endpoint].map((n,i)=>i==={xy:2,xz:1,yz:0}[measurement.plane]?0:n))):[])],minX=Math.min(...points.map(p=>p[0])),maxX=Math.max(...points.map(p=>p[0])),minY=Math.min(...points.map(p=>p[1])),maxY=Math.max(...points.map(p=>p[1])),fitScale=roadmap?Math.min(450/Math.max(1,maxX-minX),245/Math.max(1,maxY-minY))/1.1:140/(fitExtent*(pair?1:1.732)),frame=GraphScales.frame(id,view,{scale:fitScale,offsetX:roadmap?300-(minX+maxX)*fitScale/2:300,offsetY:roadmap?210+(minY+maxY)*fitScale/2:200,extent:fitExtent},()=>diagram(id,view,items,angles,unitOverride,measurement),units),extent=frame.extent,screen=p=>{const q=project(p);return [frame.offsetX+q[0]*frame.scale,frame.offsetY-q[1]*frame.scale];},origin=screen([0,0,0]);
  let output='<rect width="600" height="400" fill="#141b24"/><defs>'+items.map((item,i)=>`<marker id="${id}Arrow${i}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10Z" fill="${item.color}"/></marker>`).join('')+'</defs>';
  output+=GraphScales.axesSVG(view,screen,extent,units,400,roadmap?extent:Infinity);
  if(measurement){const item=items[measurement.index],plane=measurement.plane,drop={xy:2,xz:1,yz:0}[plane];if(item&&drop!==undefined){const a=item.start.map((v,i)=>i===drop?0:v),b=item.end.map((v,i)=>i===drop?0:v),sa=screen(a),sb=screen(b);output+=`<g class="plane-measurement"><path d="M${screen(item.start)}L${sa}M${screen(item.end)}L${sb}" fill="none" stroke="#d6b6ff" stroke-width="1.5" stroke-dasharray="4 5"/><line x1="${sa[0]}" y1="${sa[1]}" x2="${sb[0]}" y2="${sb[1]}" stroke="#d6b6ff" stroke-width="3" stroke-dasharray="7 4" marker-end="url(#${id}Arrow${measurement.index})"/><circle cx="${sb[0]}" cy="${sb[1]}" r="4" fill="#d6b6ff"/><text x="${sb[0]+10}" y="${sb[1]-14}" fill="#d6b6ff" font-size="13">${measurement.directionOnly?plane+' direction projection':plane+' landing '+M.esc(tuple(b))}</text></g>`;}}
  items.forEach((item,i)=>{const a=screen(item.start),b=screen(item.end),zero=Math.hypot(...item.end.map((v,j)=>v-item.start[j]))<1e-10;output+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${item.color}" stroke-width="${item.dashed?1.5:3}" ${item.dashed?'stroke-dasharray="5 5"':''} ${item.arrow&&!zero?`marker-end="url(#${id}Arrow${i})"`:''}/><circle cx="${b[0]}" cy="${b[1]}" r="3" fill="${item.color}"/><text x="${b[0]+10}" y="${b[1]+(i%2?-10:18)}" fill="${item.color}" font-size="12">${M.esc(item.label)}</text>`;});
  for(const item of items){const right=item.rightAngle;if(!right)continue;const size=extent*.035,corner=(a,b)=>screen(right.origin.map((v,i)=>v+size*(a*right.first[i]+b*right.second[i])));output+=`<path class="right-angle-marker" d="M${corner(1,0)}L${corner(1,1)}L${corner(0,1)}" fill="none" stroke="#d6b6ff" stroke-width="2"/>`;}
  for(const angle of angles)output+=GraphScales.spatialAngle(screen,angle.origin,angle.first,angle.second,extent*.18,angle.label);if(view==='iso'&&angles.length)output+='<text x="12" y="390" fill="#b9c7d8" font-size="11">Angle values are true 3D angles; arcs are projected.</text>';
  output+=`<circle cx="${origin[0]}" cy="${origin[1]}" r="3" fill="#94a3b8"/><text x="${origin[0]-15}" y="${origin[1]+18}" fill="#94a3b8">0</text>`;GraphScales.paint($(id),output);
 }
 function practice({id,title,cases,targets,solution,hints}){
  let index=0,hintIndex=0;const host=$(id);host.innerHTML=`<div class="eyebrow">GUIDED PRACTICE</div><h2>${title}</h2><label>Problem type<select id="${id}Case">${cases.map((c,i)=>`<option value="${i}">${c.name}</option>`).join('')}</select></label><p id="${id}Problem" class="position-problem"></p><div id="${id}Inputs" class="position-answer-grid"></div><div class="actions"><button id="${id}Check" class="primary">Check answers</button><button id="${id}Hint">Show a hint</button><button id="${id}Reveal">Show worked solution</button></div><p id="${id}Feedback" class="practice-feedback" role="status"></p><p id="${id}HintText" class="practice-hint"></p><div id="${id}Solution" hidden></div>`;
  function render(){hintIndex=0;$(id+'Problem').innerHTML=cases[index].problem;$(id+'Inputs').innerHTML=targets(cases[index]).map((target,i)=>`<label>${target.label}<input id="${id}Answer${i}" type="number" step="any"></label>`).join('');$(id+'Feedback').textContent='';$(id+'HintText').textContent='';$(id+'Solution').hidden=true;}
  $(id+'Case').onchange=()=>{index=Number($(id+'Case').value);render();};
  $(id+'Check').onclick=()=>{const expected=targets(cases[index]),values=expected.map((_,i)=>$(id+'Answer'+i).value);if(values.some(v=>v.trim()===''||!Number.isFinite(Number(v)))){$(id+'Feedback').textContent='Fill in every answer, including zero components.';return;}$(id+'Feedback').textContent=values.every((v,i)=>Math.abs(Number(v)-expected[i].value)<=expected[i].tolerance)?'Correct. Your signed values and components match.':cases[index].feedback;};
  $(id+'Hint').onclick=()=>{$(id+'HintText').textContent=hints[Math.min(hintIndex++,hints.length-1)];};$(id+'Reveal').onclick=()=>{$(id+'Solution').innerHTML=solution(cases[index]);$(id+'Solution').hidden=false;};render();
 }
 return {axes,round,num,text,tuple,vec,fields,read,sync,row,symbols,diagram,practice};
})();
